struct Cut {long n=0,pos=0,neg=0,zero=0;long double sum=0,sq=0,abs=0;void add(double w){++n;sum+=w;sq+=(long double)w*w;abs+=std::abs(w);if(w>0)++pos;else if(w<0)++neg;else++zero;}};
void native_methods(){using atlas_hh::delphes::polar;auto a=polar(60,0,0,0),b=polar(60,0,std::acos(-1.),0);demand(std::abs((a+b).mass()-120)<1e-10,"mass method regression");demand(!atlas_hh::delphes::photon_fiducial(25,0)&&atlas_hh::delphes::photon_fiducial(25.001,0),"photon strict threshold regression");demand(atlas_hh::delphes::photon_fiducial(40,1.37)&&!atlas_hh::delphes::photon_fiducial(40,1.4),"crack regression");std::cout<<Json{{"status","PASS_NATIVE_PHYSICS_METHOD_TESTS"},{"evidence_class","SYNTHETIC_METHOD_TEST"},{"physical_events",0},{"RooFit_methods","SEPARATE_phase8_methods_methods-test"}}.dump(2)<<'\n';}
